/*
 * Resets betting screen state, selection grids, available total, and timer values.
 */
// FUNCTION: FF7 0x00776375
void __cdecl Mini_ChocoboRaceResetBetScreen(void)
{
    g_pChocoboSoundCommand->soundCommand = SOUND_MUSIC_PLAY;
    g_pChocoboSoundCommand->soundArg = 0x3D;
    SoundDispatchCommand((short)g_pChocoboSoundCommand->soundCommand, g_pChocoboSoundCommand->soundArg, 0, 0, 0, 0, 0, 0, 0);
    Mini_ChocoboRaceResetDebugTuningValues();
    Mini_ChocoboRaceBuildBetGrid();
    g_ChocoboBetStepIndex = 0;
    g_ChocoboBetGridRow = 0;
    g_ChocoboBetGridCol = g_ChocoboBetGridRow;
    g_ChocoboBetScreenState = g_ChocoboBetGridCol;
    g_ChocoboBetSlotIndex = 0;
    g_ChocoboBetWork[2] = 0xFFFFFFFF;
    g_ChocoboBetWork[1] = g_ChocoboBetWork[2];
    g_ChocoboBetWork[0] = g_ChocoboBetWork[1];
    g_ChocoboBetCursorHighlight = g_ChocoboBetWork[0];
    g_ChocoboBetClearedWord = 0;
}
