/*
 * Resets chocobo result state, sound commands, and determines place winners.
 */
// FUNCTION: FF7 0x00778a3c
void __cdecl Mini_ChocoboRaceBeginResultScreen(void)
{
    unsigned short i;

    g_ChocoboBetCursorHighlight = 0xFFFFFFFF;
    g_ChocoboResultTimer = 0;
    g_pChocoboSoundCommand->soundCommand = SOUND_MUSIC_VOLUME_TRANS;
    g_pChocoboSoundCommand->soundArg = 0x1E;
    g_pChocoboSoundCommand->soundParam1 = 0x1E;
    SoundDispatchCommand((short)g_pChocoboSoundCommand->soundCommand, g_pChocoboSoundCommand->soundArg, g_pChocoboSoundCommand->soundParam1, 0, 0, 0, 0, 0, 0);
    Mini_ChocoboRaceSendSoundCommand23();
    g_ChocoboFadeStep = 0xFFFFFFF0;
    g_ChocoboFadeLevel = 0xFF;
    g_ChocoboBetClearedWord = 0;
    g_pChocoboSoundCommand->soundCommand = SOUND_MUSIC_PLAY;
    g_pChocoboSoundCommand->soundArg = 0;
    SoundDispatchCommand((short)g_pChocoboSoundCommand->soundCommand, g_pChocoboSoundCommand->soundArg, 0, 0, 0, 0, 0, 0, 0);
    for (i = 0; i < 6; i++) {
        if (g_ChocoboRacers[i].place == 1) {
            g_ChocoboWinningPairA = i;
            g_ChocoboFirstPlaceRacer = g_ChocoboWinningPairA;
        }
        if (g_ChocoboRacers[i].place == 2) {
            g_ChocoboWinningPairB = i;
        }
    }
    if (g_ChocoboWinningPairA > g_ChocoboWinningPairB) {
        i = (short)g_ChocoboWinningPairA;
        g_ChocoboWinningPairA = g_ChocoboWinningPairB;
        g_ChocoboWinningPairB = i;
    }
    for (i = 0; i < 0x10; i++) {
        if (g_ChocoboWinningPairA == g_ChocoboPairResultGridMap[i].stateA && g_ChocoboWinningPairB == g_ChocoboPairResultGridMap[i].stateB) {
            break;
        }
    }
    if (i == 0x10) {
        i = 0;
    }
    g_ChocoboBetGridCol = g_ChocoboPairResultGridMap[i].resultA;
    g_ChocoboBetGridRow = g_ChocoboPairResultGridMap[i].resultB;
}
